from flask import render_template, request, redirect, url_for, flash
from app import app, db
from app.forms import BlogPostForm, ImageUploadForm
from app.models import BlogPost, Image
from werkzeug.utils import secure_filename
import os

@app.route('/')
def index():
    posts = BlogPost.query.all()
    return render_template('index.html', posts=posts)

@app.route('/create_post', methods=['GET', 'POST'])
def create_post():
    form = BlogPostForm()
    if form.validate_on_submit():
        title = form.title.data
        content = form.content.data
        new_post = BlogPost(title=title, content=content)
        db.session.add(new_post)
        db.session.commit()
        flash('Blog post created successfully!', 'success')
        return redirect(url_for('index'))
    return render_template('create_post.html', form=form)

@app.route('/upload_image', methods=['GET', 'POST'])
def upload_image():
    form = ImageUploadForm()
    if form.validate_on_submit():
        image_file = form.image.data
        if image_file:
            filename = secure_filename(image_file.filename)
            filepath = os.path.join(app.config['UPLOAD_FOLDER'], filename)
            image_file.save(filepath)
            new_image = Image(filename=filename, filepath=filepath)
            db.session.add(new_image)
            db.session.commit()
            flash('Image uploaded successfully!', 'success')
            return redirect(url_for('index'))
    return render_template('upload_image.html', form=form)

{% extends "base.html" %}

{% block content %}
<div class="container">
    <h1>Create a New Blog Post</h1>
    <form method="post" action="{{ url_for('create_post') }}" enctype="multipart/form-data">
        {{ form.hidden_tag() }}
        <div class="form-group">
            {{ form.title.label(class="form-label") }}
            {{ form.title(class="form-control") }}
        </div>
        <div class="form-group">
            {{ form.content.label(class="form-label") }}
            {{ form.content(class="form-control", rows=5) }}
        </div>
        <div class="form-group">
            {{ image_form.image.label(class="form-label") }}
            {{ image_form.image(class="form-control-file") }}
        </div>
        <button type="submit" class="btn btn-primary">Submit</button>
    </form>

    <hr>

    <h2>Blog Posts</h2>
    {% for post in posts %}
    <div class="card my-3">
        <div class="card-body">
            <h3 class="card-title">{{ post.title }}</h3>
            <p class="card-text">{{ post.content }}</p>
            {% if post.image_url %}
            <img src="{{ post.image_url }}" alt="Image for {{ post.title }}" class="img-fluid my-2">
            {% endif %}
            <p class="text-muted">Posted on {{ post.timestamp.strftime('%Y-%m-%d %H:%M:%S') }}</p>
        </div>
    </div>
    {% else %}
    <p>No posts yet. Be the first to create one!</p>
    {% endfor %}
</div>
{% endblock %}

